with flattened as (select id, service, host, latency_ms, status_code, k, attr_value from app_logs lateral view outer explode(context) x as k, attr_value), valid as (select id, host, latency_ms, k, status_code + latency_ms as status_code_plus_latency_ms, coalesce(k, 'N/A') as k_filled from flattened where latency_ms < 1782), base as (select *, cast(latency_ms as string) as latency_ms_str, coalesce(k, 'UNKNOWN') as k_filled_2 from valid where k = 'version'), scored as (select *, dense_rank() over w_recent as latency_ms_dense_rank, rank() over (order by status_code_plus_latency_ms desc nulls first) as status_code_plus_latency_ms_rank, avg(status_code_plus_latency_ms) over (partition by k, host) as k_avg_status_code_plus_latency_ms, min(status_code_plus_latency_ms) over (partition by host) as host_min_status_code_plus_latency_ms, stddev_samp(latency_ms) over (partition by k) as k_stddev_samp_latency_ms from base window w_recent as (partition by k order by latency_ms desc nulls first)), with_windows as (select *, round(latency_ms_dense_rank / sum(latency_ms_dense_rank) over (partition by k, host), 4) as latency_ms_dense_rank_share, percent_rank() over (partition by k order by status_code_plus_latency_ms nulls last) as status_code_plus_latency_ms_percent_rank from scored), scored_app_logs as (select id, host, latency_ms, k, status_code_plus_latency_ms, k_filled, latency_ms_str, k_filled_2, latency_ms_dense_rank, status_code_plus_latency_ms_rank, k_avg_status_code_plus_latency_ms, host_min_status_code_plus_latency_ms, k_stddev_samp_latency_ms, latency_ms_dense_rank_share, status_code_plus_latency_ms_percent_rank, dense_rank() over (partition by host order by latency_ms_dense_rank_share nulls last) as latency_ms_dense_rank_share_dense_rank, rank() over w_hist as latency_ms_rank from with_windows window w_hist as (partition by host order by latency_ms desc nulls last)), metrics as (select *, cume_dist() over (partition by k order by latency_ms_dense_rank_share_dense_rank desc nulls first) as latency_ms_dense_rank_share_dense_rank_cume_dist, rank() over (partition by host order by latency_ms_dense_rank_share_dense_rank desc nulls first) as latency_ms_dense_rank_share_dense_rank_rank, round(latency_ms_dense_rank / sum(latency_ms_dense_rank) over (partition by host), 4) as latency_ms_dense_rank_share_2 from scored_app_logs) select k, round(avg(status_code_plus_latency_ms_rank), 2) as avg_status_code_plus_latency_ms_rank, count_if(host = 'h4') as h4_events, max(host_min_status_code_plus_latency_ms) as max_host_min_status_code_plus_latency_ms, count(distinct id) as distinct_ids, size(collect_set(k)) as num_ks from metrics group by k
